/* ================= 방문예약 : 모든 조회 · 검색 · 통계 · 다운로드가 "내 권한의 사이트" 안에서만 동작 (URL 의 site · advertiser 값을 바꿔도 다른 광고주 자료는 나오지 않음) ================= */
function wb_sub_sites($c, $siteParam) { $all = array(); foreach (wb_sites($c['user']) as $s) { if (wb_can($c['user'], (int)$s['id'], 'submissions') || wb_can($c['user'], (int)$s['id'], 'submissions.view')) { $all[] = $s; } } $adv = wb_int(wb_q($c, 'advertiser')); if ($adv) { $all = array_values(array_filter($all, function ($s) use ($adv) { return (int)$s['advertiser_id'] === $adv; })); } if ($siteParam === null || $siteParam === '' || $siteParam === 'all') { return $all; } foreach ($all as $s) { if ((int)$s['id'] === wb_int($siteParam)) { return array($s); } } throw new WbHttpError(403, '해당 사이트의 예약을 볼 권한이 없습니다.'); }
function wb_sub_ids($sites) { $ids = array(); foreach ($sites as $s) { $ids[] = (int)$s['id']; } return $ids; }
function wb_sub_filters($c, $sites) {
  $ids = wb_sub_ids($sites); $where = array('s.site_id IN (' . (count($ids) ? wb_in($ids) : '0') . ')', 's.deleted_at IS NULL'); $params = $ids; $q = $c['query']; $st = wb_statuses();
  if (isset($q['gs']) && $q['gs'] === 'failed') { $where[] = "EXISTS (SELECT 1 FROM google_sheet_sync_logs g WHERE g.reservation_id = s.id AND g.status = 'failed')"; }   /* 알림 › Google Sheets 실패 예약 보기 */
  if (isset($q['status']) && $q['status'] === 'pending') { $where[] = "s.status IN ('new','checking')"; } elseif (!empty($q['status']) && isset($st[$q['status']])) { $where[] = 's.status = ?'; $params[] = $q['status']; }
  if (!empty($q['from'])) { $where[] = 's.created_at >= ?'; $params[] = $q['from'] . ' 00:00:00'; } if (!empty($q['to'])) { $where[] = 's.created_at <= ?'; $params[] = $q['to'] . ' 23:59:59'; }
  if (!empty($q['vfrom'])) { $where[] = 's.visit_date >= ?'; $params[] = $q['vfrom']; } if (!empty($q['vto'])) { $where[] = 's.visit_date <= ?'; $params[] = $q['vto']; } if (!empty($q['vtime'])) { $where[] = 's.visit_time = ?'; $params[] = $q['vtime']; }
  if (!empty($q['assignee']) && wb_int($q['assignee'])) { $where[] = 's.assignee_id = ?'; $params[] = wb_int($q['assignee']); }
  if (!empty($q['name'])) { $where[] = 's.name LIKE ?'; $params[] = '%' . $q['name'] . '%'; } if (!empty($q['phone'])) { $where[] = "REPLACE(s.phone, '-', '') LIKE ?"; $params[] = '%' . preg_replace('/[^0-9]/', '', $q['phone']) . '%'; }
  if (!empty($q['q'])) { $digits = preg_replace('/\D+/', '', (string)$q['q']); $where[] = '(s.name LIKE ? OR s.phone LIKE ? OR s.receipt_no LIKE ? OR s.data_json LIKE ? OR s.memo LIKE ?' . (strlen($digits) >= 3 ? " OR REPLACE(s.phone, '-', '') LIKE ?" : '') . ')'; $like = '%' . $q['q'] . '%'; array_push($params, $like, $like, $like, $like, $like); if (strlen($digits) >= 3) { $params[] = '%' . $digits . '%'; } }
  return array('where' => implode(' AND ', $where), 'params' => $params);
}
/* 고객이 입력한 문의사항 원문 (폼의 여러 줄 입력칸 · 제출 당시 항목 기준) — 목록 미리보기 · 전체 보기용 (DB 원문은 그대로) */
function wb_sub_inquiry($s, $data) {
  if (!is_array($data) || !empty($data['_purged'])) { return ''; }
  $key = ''; foreach ((array)wb_json_safe($s['fields_json'], array()) as $f) { $f = wb_arr($f); if (isset($f['type']) && $f['type'] === 'textarea' && !empty($f['name'])) { $key = $f['name']; break; } }
  if ($key === '') { foreach (array('memo', 'message', 'inquiry', 'question', 'content', 'comment') as $k) { if (isset($data[$k])) { $key = $k; break; } } }
  if ($key === '' || !isset($data[$key])) { return ''; }
  $v = $data[$key]; return trim(is_array($v) ? implode(', ', $v) : (string)$v);
}
function wb_sub_out($c, $s, $full) {
  $can = wb_can($c['user'], (int)$s['site_id'], 'submissions'); $st = wb_statuses(); $data = wb_arr($s['data_json']);
  $o = array('id' => (int)$s['id'], 'receipt_no' => $s['receipt_no'] ? $s['receipt_no'] : ('#' . $s['id']), 'site_id' => (int)$s['site_id'], 'site_key' => (string)$s['site_key'], 'site_name' => $s['site_name'], 'consent' => (string)$s['consent'], 'memo_preview' => $can && $s['memo'] ? wb_substr(trim(preg_replace('/\s+/', ' ', $s['memo'])), 60) : '', 'name' => $s['name'], 'phone' => wb_mask_phone($s['phone'], $can), 'tel' => $can ? 'tel:' . preg_replace('/[^0-9+]/', '', (string)$s['phone']) : '', 'visit_date' => $s['visit_date'], 'visit_time' => $s['visit_time'], 'status' => $s['status'], 'status_label' => isset($st[$s['status']]) ? $st[$s['status']] : $s['status'], 'created_at' => $s['created_at'], 'assignee' => isset($s['assignee_name']) && $s['assignee_name'] !== null ? $s['assignee_name'] : null, 'assignee_id' => $s['assignee_id'] ? (int)$s['assignee_id'] : null, 'form' => isset($s['form_name']) ? $s['form_name'] : null, 'device' => $s['device'] ? $s['device'] : null, 'page_path' => $s['page_path'], 'utm' => wb_json_safe($s['utm_json'], new stdClass()), 'has_memo' => !empty($s['memo']), 'channel' => $s['channel'] ? $s['channel'] : 'direct', 'inquiry' => wb_sub_inquiry($s, $data));
  if ($full) { if (!$can) { foreach ($data as $k => $v) { if (preg_match('/phone|tel|email/i', $k)) { $data[$k] = wb_mask_phone(is_array($v) ? implode(',', $v) : (string)$v, false); } } } $o['data'] = count($data) ? $data : new stdClass(); $o['fields'] = wb_json_safe($s['fields_json'], array()); $o['memo'] = $s['memo']; $o['referrer'] = $s['referrer']; $o['ua'] = $s['ua']; $o['retention_until'] = $s['retention_until']; $o['anonymized_at'] = $s['anonymized_at']; $o['form_version'] = $s['form_version'] === null ? null : (int)$s['form_version']; $o['updated_at'] = $s['updated_at']; $o['updated_by'] = $s['updated_by'] ? (string)wb_val('SELECT name FROM users WHERE id = ?', array((int)$s['updated_by'])) : ''; $o['advertiser_id'] = $s['advertiser_id'] ? (int)$s['advertiser_id'] : null; $o['landing_path'] = (string)$s['landing_path']; $o['consent'] = $s['consent'] ? $s['consent'] : (isset($data['agreePrivacy']) ? $data['agreePrivacy'] : (isset($data['consent']) ? $data['consent'] : '')); }
  return $o;
}
function wb_access($c, $siteId, $action, $subId = null, $detail = '') { wb_insert('submission_access_logs', array('site_id' => $siteId ? (int)$siteId : null, 'user_id' => (int)$c['user']['id'], 'submission_id' => $subId ? (int)$subId : null, 'action' => $action, 'detail' => wb_str($detail, 190), 'ip_hash' => $c['ipHash'], 'created_at' => wb_now())); }
function wb_sub_of($c, $id, $ability = null) { $s = wb_get('SELECT s.*, f.name AS form_name, u.name AS assignee_name, st.name AS site_name FROM form_submissions s JOIN forms f ON f.id = s.form_id JOIN sites st ON st.id = s.site_id LEFT JOIN users u ON u.id = s.assignee_id WHERE s.id = ? AND s.deleted_at IS NULL', array((int)$id)); if (!$s) { throw new WbHttpError(404, '예약 정보를 찾을 수 없습니다.'); } $sid = (int)$s['site_id']; if (!(wb_can($c['user'], $sid, $ability ? $ability : 'submissions.view') || wb_can($c['user'], $sid, 'submissions'))) { throw new WbHttpError(403, '권한이 없습니다.'); } if ($ability && $ability !== 'submissions.view') { wb_must($c['user'], $sid, $ability); } return $s; }
function wb_history($c, $id, $field, $before, $after) { if ((string)($before === null ? '' : $before) === (string)($after === null ? '' : $after)) { return; } wb_insert('submission_histories', array('submission_id' => (int)$id, 'user_id' => (int)$c['user']['id'], 'field' => $field, 'before_value' => $before === null ? null : wb_str($before, 2000), 'after_value' => $after === null ? null : wb_str($after, 2000), 'created_at' => wb_now())); }
function wb_anonymize($id) { wb_update('form_submissions', array('data_json' => wb_enc(array('_purged' => true)), 'name' => '(파기)', 'phone' => '', 'memo' => null, 'ua' => null, 'referrer' => null, 'anonymized_at' => wb_now(), 'updated_at' => wb_now()), 'id = ?', array((int)$id)); }
function wb_purge_expired($siteId = 0) { $rows = wb_all('SELECT id FROM form_submissions WHERE anonymized_at IS NULL AND retention_until IS NOT NULL AND retention_until < ?' . ($siteId ? ' AND site_id = ?' : ''), $siteId ? array(wb_today(), (int)$siteId) : array(wb_today())); foreach ($rows as $r) { wb_anonymize((int)$r['id']); } return count($rows); }
wb_route('GET', '/submissions', function ($c) {
  $sites = wb_sub_sites($c, wb_q($c, 'site', null)); $f = wb_sub_filters($c, $sites); $q = $c['query'];
  $page = max(1, wb_int(isset($q['page']) ? $q['page'] : 1, 1)); $per = min(200, max(5, wb_int(isset($q['per']) ? $q['per'] : 20, 20))); $sort = isset($q['sort']) && in_array($q['sort'], array('created_at', 'visit_date', 'status', 'name'), true) ? $q['sort'] : 'created_at'; $dir = isset($q['dir']) && $q['dir'] === 'asc' ? 'ASC' : 'DESC';
  $total = wb_int(wb_val('SELECT COUNT(*) FROM form_submissions s WHERE ' . $f['where'], $f['params']));
  $rows = wb_all('SELECT s.*, f.name AS form_name, u.name AS assignee_name, st.name AS site_name FROM form_submissions s JOIN forms f ON f.id = s.form_id JOIN sites st ON st.id = s.site_id LEFT JOIN users u ON u.id = s.assignee_id WHERE ' . $f['where'] . ' ORDER BY s.' . $sort . ' ' . $dir . ', s.id DESC LIMIT ' . $per . ' OFFSET ' . (($page - 1) * $per), $f['params']);
  if (count($sites)) { wb_access($c, count($sites) === 1 ? (int)$sites[0]['id'] : null, 'list', null, wb_substr(wb_enc($q), 200)); }
  $ids = wb_sub_ids($sites); $in = count($ids) ? wb_in($ids) : '0';
  $cnt = function ($w, $p = array()) use ($ids, $in) { return wb_int(wb_val('SELECT COUNT(*) FROM form_submissions WHERE site_id IN (' . $in . ') AND deleted_at IS NULL' . $w, array_merge($ids, $p))); };
  $stats = array('total' => $cnt(''), 'today' => $cnt(' AND created_at >= ?', array(wb_today() . ' 00:00:00')), 'new' => $cnt(" AND status = 'new'"), 'pending' => $cnt(" AND status IN ('new','checking')"), 'confirmed' => $cnt(" AND status = 'confirmed'"), 'month' => $cnt(' AND created_at >= ?', array(substr(wb_today(), 0, 7) . '-01 00:00:00')));
  $assignees = count($ids) ? array_map(function ($r) { return wb_ints($r, array('id')); }, wb_all("SELECT DISTINCT u.id, u.name FROM users u WHERE u.status = 'active' AND (u.role = 'super' OR EXISTS (SELECT 1 FROM site_users su WHERE su.user_id = u.id AND su.site_id IN (" . $in . '))) ORDER BY u.name', $ids)) : array();
  $visitTimes = wb_visit_times(); if (count($sites) === 1) { $fr = wb_get("SELECT settings_json FROM forms WHERE site_id = ? AND `key` = 'reserve'", array((int)$sites[0]['id'])); $vt = $fr ? wb_prop(wb_json_safe($fr['settings_json'], null), 'visitTimes') : null; if (is_array($vt) && count($vt)) { $visitTimes = $vt; } }
  $out = array(); foreach ($rows as $r) { $out[] = wb_sub_out($c, $r, false); } $smsMap = wb_sms_summary_map(array_map(function ($o) { return $o['id']; }, $out)); foreach ($out as $i => $o) { $out[$i]['sms'] = isset($smsMap[$o['id']]) ? $smsMap[$o['id']] : null; }
  $gsMap = array(); if (function_exists('wb_gs_status_map')) { try { $gsMap = wb_gs_status_map(array_map(function ($o) { return $o['id']; }, $out)); } catch (Throwable $e) { $gsMap = array(); } } foreach ($out as $i => $o) { $out[$i]['gs'] = isset($gsMap[$o['id']]) ? $gsMap[$o['id']] : null; }
  $dupKeys = array(); foreach ($rows as $r) { $dg = preg_replace('/[^0-9]/', '', (string)$r['phone']); if (strlen($dg) >= 8) { $dupKeys[(int)$r['site_id'] . '|' . $dg] = array((int)$r['site_id'], $dg); } } $dupN = array();
  foreach ($dupKeys as $k => $v) { $dupN[$k] = wb_int(wb_val("SELECT COUNT(*) FROM form_submissions WHERE site_id = ? AND REPLACE(REPLACE(REPLACE(phone, '-', ''), ' ', ''), '.', '') = ? AND deleted_at IS NULL", array($v[0], $v[1]))); }
  foreach ($rows as $i => $r) { $k = (int)$r['site_id'] . '|' . preg_replace('/[^0-9]/', '', (string)$r['phone']); $out[$i]['dup'] = isset($dupN[$k]) ? max(0, $dupN[$k] - 1) : 0; } $canManage = true; $siteList = array(); foreach ($sites as $s) { if (!wb_can($c['user'], (int)$s['id'], 'submissions')) { $canManage = false; } $siteList[] = array('id' => (int)$s['id'], 'name' => $s['name']); }
  return array('rows' => $out, 'total' => $total, 'page' => $page, 'pages' => max(1, (int)ceil($total / $per)), 'stats' => $stats, 'statuses' => wb_statuses(), 'assignees' => $assignees, 'sites' => $siteList, 'visitTimes' => $visitTimes, 'canManage' => $canManage);
});
wb_route('GET', '/submissions/export.csv', function ($c) {
  $sites = wb_sub_sites($c, wb_q($c, 'site', null)); $okAll = count($sites) > 0; foreach ($sites as $s) { if (!wb_can($c['user'], (int)$s['id'], 'submissions.export')) { $okAll = false; } } if (!$okAll) { throw new WbHttpError(403, '다운로드 권한이 없습니다. (광고주 관리자 · 최고관리자만)'); }
