  $labels = array(); $ids = wb_sub_ids($sites); foreach (wb_all('SELECT ff.key, ff.label FROM form_fields ff JOIN forms fm ON fm.id = ff.form_id WHERE fm.site_id IN (' . (count($ids) ? wb_in($ids) : '0') . ')', $ids) as $l) { $labels[$l['key']] = $l['label']; } if (empty($labels['agreePrivacy'])) { $labels['agreePrivacy'] = '개인정보 동의'; }
