  $out = "\xEF\xBB\xBF" . wb_csv_line($head);
  foreach ($rows as $r) { $d = wb_arr($r['data_json']); $line = array($r['receipt_no'] ? $r['receipt_no'] : $r['id'], $r['site_name'], (string)$r['site_key'], $r['created_at'], isset($st[$r['status']]) ? $st[$r['status']] : $r['status'], $r['name'], $r['phone'], $r['visit_date'], $r['visit_time'], (string)$r['assignee_name']); foreach ($keys as $k) { $line[] = isset($d[$k]) ? (is_array($d[$k]) ? implode(', ', $d[$k]) : $d[$k]) : ''; } $line = array_merge($line, array((string)$r['memo'], (string)$r['device'], $r['landing_path'] ? $r['landing_path'] : (string)$r['page_path'], (string)$r['page_path'], (string)$r['referrer'], (string)$r['utm_json'], (string)$r['retention_until'])); $out .= wb_csv_line($line); }
  wb_access($c, $one, 'export', null, 'CSV ' . count($rows) . '건'); wb_log($c, $one, 'submission.export', 'submission', null, '예약 CSV 다운로드 ' . count($rows) . '건');
  wb_send_file(200, 'text/csv; charset=utf-8', $out, '방문예약_' . str_replace('-', '', wb_today()) . '.csv'); return null;
});
wb_route('POST', '/submissions/bulk', function ($c) { $ids = array(); foreach ((array)wb_b($c, 'ids', array()) as $x) { if (wb_int($x)) { $ids[] = wb_int($x); } } if (!count($ids)) { throw new WbHttpError(422, '선택된 예약이 없습니다.'); } $rows = wb_all('SELECT id, site_id, status FROM form_submissions WHERE id IN (' . wb_in($ids) . ') AND deleted_at IS NULL', $ids); $action = wb_str(wb_b($c, 'action')); $st = wb_statuses(); $n = 0; foreach ($rows as $r) { $sid = (int)$r['site_id']; if ($action === 'delete') { wb_must($c['user'], $sid, 'delete'); wb_update('form_submissions', array('deleted_at' => wb_now()), 'id = ?', array((int)$r['id'])); $n++; } elseif (isset($st[$action])) { wb_must($c['user'], $sid, 'submissions'); if ($r['status'] !== $action) { wb_history($c, (int)$r['id'], 'status', isset($st[$r['status']]) ? $st[$r['status']] : $r['status'], $st[$action]); } wb_update('form_submissions', array('status' => $action, 'updated_at' => wb_now(), 'updated_by' => (int)$c['user']['id']), 'id = ?', array((int)$r['id'])); $n++; if ($r['status'] !== $action && function_exists('wb_gs_queue_status')) { try { wb_gs_queue_status($c, (int)$r['id']); } catch (Throwable $e) {} } } elseif ($action === 'assign') { wb_must($c['user'], $sid, 'submissions'); wb_update('form_submissions', array('assignee_id' => wb_int(wb_b($c, 'assignee_id')) ? wb_int(wb_b($c, 'assignee_id')) : null, 'updated_at' => wb_now(), 'updated_by' => (int)$c['user']['id']), 'id = ?', array((int)$r['id'])); $n++; } else { throw new WbHttpError(422, '알 수 없는 작업입니다.'); } } wb_log($c, null, 'submission.bulk', 'submission', null, '예약 ' . $n . '건 일괄 ' . $action); return array('count' => $n); });
wb_route('GET', '/submissions/:id', function ($c, $p) { $s = wb_sub_of($c, $p['id']); wb_access($c, (int)$s['site_id'], 'view', (int)$s['id']); $labels = array(); foreach ((array)wb_json_safe($s['fields_json'], array()) as $f) { $f = wb_arr($f); if (!empty($f['name'])) { $labels[$f['name']] = !empty($f['label']) ? $f['label'] : $f['name']; } } if (!count($labels)) { $sc = wb_form_schema((int)$s['form_id']); foreach ($sc['fields'] as $f) { $f = wb_arr($f); $labels[$f['name']] = $f['label']; } foreach ((array)wb_prop($sc['settings'], 'agreements', array()) as $a) { $a = wb_arr($a); if (!empty($a['name'])) { $labels[$a['name']] = isset($a['label']) ? $a['label'] : ''; } } } if (empty($labels['agreePrivacy'])) { $labels['agreePrivacy'] = '개인정보 수집 · 이용 동의'; } $o = wb_sub_out($c, $s, true); $o['labels'] = $labels; $o['history'] = wb_all('SELECT h.field, h.before_value, h.after_value, h.created_at, u.name AS user_name FROM submission_histories h LEFT JOIN users u ON u.id = h.user_id WHERE h.submission_id = ? ORDER BY h.id DESC LIMIT 50', array((int)$s['id'])); $o['access'] = wb_all('SELECT l.action, l.detail, l.created_at, u.name AS user_name FROM submission_access_logs l LEFT JOIN users u ON u.id = l.user_id WHERE l.submission_id = ? ORDER BY l.id DESC LIMIT 20', array((int)$s['id'])); $o['sms'] = wb_sms_logs_of((int)$s['id']); $smsCfg = wb_sms_cfg($c); $o['smsState'] = array('ready' => wb_sms_ready($smsCfg) === '', 'test' => in_array($smsCfg['provider'], array('log', 'fail'), true)); if (function_exists('wb_gs_detail')) { try { $o['gsheets'] = wb_gs_detail($s); } catch (Throwable $e) { $o['gsheets'] = null; } } $o['smsCanResend'] = wb_can($c['user'], (int)$s['site_id'], 'submissions'); $o['smsNoPhone'] = function_exists('wb_sms_missing_phone') ? wb_sms_missing_phone((int)$s['site_id']) : array(); return array('submission' => $o); });
wb_route('POST', '/submissions/:id/sms/resend', function ($c, $p) { $s = wb_sub_of($c, $p['id'], 'submissions'); if (!wb_rate('smsresend:' . (int)$s['id'], 5, 60)) { throw new WbHttpError(429, '잠시 후 다시 시도해 주세요.'); } $r = wb_sms_resend($c, (int)$s['site_id'], (int)$s['id']); wb_log($c, (int)$s['site_id'], 'submission.sms_resend', 'submission', (int)$s['id'], '예약 #' . $s['id'] . ' 문자 다시 보내기 · 성공 ' . $r['sent'] . ' · 실패 ' . $r['failed']); $r['sms'] = wb_sms_logs_of((int)$s['id']); return $r; });
wb_route('PATCH', '/submissions/:id', function ($c, $p) {
  $s = wb_sub_of($c, $p['id'], 'submissions'); $d = array('updated_at' => wb_now(), 'updated_by' => (int)$c['user']['id']); $changes = array(); $b = $c['body']; $st = wb_statuses();
  if (!empty($b['expect_updated_at']) && $s['updated_at'] && (string)$b['expect_updated_at'] !== (string)$s['updated_at']) { $who = $s['updated_by'] ? (string)wb_val('SELECT name FROM users WHERE id = ?', array((int)$s['updated_by'])) : ''; throw new WbHttpError(409, '다른 관리자' . ($who !== '' ? '(' . $who . ')' : '') . '가 ' . substr((string)$s['updated_at'], 5, 11) . ' 에 먼저 수정했습니다. 최신 내용을 확인한 뒤 다시 저장해 주세요.', array('conflict' => true, 'updated_at' => $s['updated_at'])); }
  if (wb_has($b, 'status') && isset($st[$b['status']]) && $b['status'] !== $s['status']) { $d['status'] = $b['status']; wb_history($c, (int)$s['id'], 'status', isset($st[$s['status']]) ? $st[$s['status']] : $s['status'], $st[$b['status']]); $changes[] = '상태 → ' . $st[$b['status']]; }
  if (wb_has($b, 'assignee_id')) { $aid = wb_int($b['assignee_id']) ? wb_int($b['assignee_id']) : null; if ($aid !== ($s['assignee_id'] ? (int)$s['assignee_id'] : null)) { $d['assignee_id'] = $aid; $name = $aid ? (string)wb_val('SELECT name FROM users WHERE id = ?', array($aid)) : '(없음)'; wb_history($c, (int)$s['id'], 'assignee', $s['assignee_name'] ? $s['assignee_name'] : '(없음)', $name); $changes[] = '담당자 → ' . $name; } }
  if (wb_has($b, 'memo')) { $memo = wb_str($b['memo'], 3000); if ($memo !== (string)$s['memo']) { $d['memo'] = $memo; wb_history($c, (int)$s['id'], 'memo', $s['memo'], $memo); $changes[] = '메모 수정'; } }
  if (count($d) > 2) { wb_update('form_submissions', $d, 'id = ?', array((int)$s['id'])); wb_access($c, (int)$s['site_id'], 'update', (int)$s['id'], implode(' · ', $changes)); wb_log($c, (int)$s['site_id'], 'submission.update', 'submission', (int)$s['id'], '예약 #' . $s['id'] . ' ' . implode(' · ', $changes)); }
  if (isset($d['status']) && function_exists('wb_gs_queue_status')) { try { wb_gs_queue_status($c, (int)$s['id']); } catch (Throwable $e) { wb_log_error('gsheets status queue: ' . $e->getMessage()); } }
  $ns = isset($d['status']) ? $d['status'] : $s['status']; return array('status' => $ns, 'status_label' => isset($st[$ns]) ? $st[$ns] : $ns, 'changes' => $changes, 'updated_at' => count($d) > 2 ? $d['updated_at'] : $s['updated_at']);
});
