function wb_http_get($url, $timeout = 15) { if (function_exists('curl_init')) { $ch = curl_init($url); curl_setopt_array($ch, array(CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => $timeout, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3, CURLOPT_USERAGENT => 'webbuilder')); $body = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); $type = (string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE); curl_close($ch); return array('ok' => $body !== false && $code >= 200 && $code < 300, 'status' => $code, 'body' => $body === false ? '' : $body, 'type' => $type); } $ctx = stream_context_create(array('http' => array('timeout' => $timeout, 'follow_location' => 1, 'user_agent' => 'webbuilder'))); $body = @file_get_contents($url, false, $ctx); $code = 0; if (isset($http_response_header[0]) && preg_match('/\s(\d{3})\s/', $http_response_header[0], $m)) { $code = (int)$m[1]; } return array('ok' => $body !== false && $code >= 200 && $code < 300, 'status' => $code, 'body' => $body === false ? '' : $body, 'type' => ''); }
wb_route('POST', '/media/import', function ($c) { $s = wb_current_site($c, 'media'); $url = wb_str(wb_b($c, 'url'), 1000); $allowed = array(); foreach (array($s['public_url'], $s['preview_url']) as $u) { $h = wb_host_of((string)$u); if ($h !== '') { $allowed[] = $h; } } if (!preg_match('#^https?://#i', $url) || !in_array(wb_host_of($url), $allowed, true)) { throw new WbHttpError(422, '등록된 공개 홈페이지 주소의 이미지만 가져올 수 있습니다.'); } $res = wb_http_get($url); if (!$res['ok']) { throw new WbHttpError(422, '이미지를 가져오지 못했습니다. (' . $res['status'] . ')'); } $tmp = tempnam(sys_get_temp_dir(), 'wbimp'); file_put_contents($tmp, $res['body']); $name = basename((string)parse_url($url, PHP_URL_PATH)); if ($name === '' || $name === '/') { $name = 'import.jpg'; } try { $m = wb_store_upload($c, $s, array('field' => 'file', 'name' => $name, 'tmp' => $tmp, 'size' => strlen($res['body']), 'type' => $res['type']), array('alt' => '')); } catch (Exception $e) { @unlink($tmp); throw $e; } @unlink($tmp); return array('media' => $m); });
wb_route('PATCH', '/media/:id', function ($c, $p) { $m = wb_media_of($c, $p['id'], 'media'); $d = array(); $b = $c['body']; if (wb_has($b, 'alt')) { $d['alt'] = wb_str($b['alt'], 190); } if (wb_has($b, 'name')) { $d['original_name'] = wb_str($b['name'], 190); } if (wb_has($b, 'folder_id')) { $d['folder_id'] = wb_int($b['folder_id']) ? wb_int($b['folder_id']) : null; } if (count($d)) { wb_update('media', $d, 'id = ?', array((int)$m['id'])); } return array('media' => wb_media_out(wb_get('SELECT * FROM media WHERE id = ?', array((int)$m['id'])), wb_media_base($c))); });
wb_route('GET', '/media/:id/usages', function ($c, $p) { return array('usages' => wb_usages_of($c, wb_media_of($c, $p['id']))); });
wb_route('DELETE', '/media/:id', function ($c, $p) {
  $m = wb_media_of($c, $p['id'], 'media'); $usages = wb_usages_of($c, $m); $live = array(); $hist = array(); foreach ($usages as $u) { if ($u['scope'] === 'live') { $live[] = $u; } else { $hist[] = $u; } }
  if (count($live)) { $names = array(); foreach (array_slice($live, 0, 3) as $u) { $names[] = $u['title']; } throw new WbHttpError(409, '사용 중인 파일은 삭제할 수 없습니다. (' . implode(', ', $names) . (count($live) > 3 ? ' 외 ' . (count($live) - 3) . '곳' : '') . ') 사용하는 곳에서 먼저 다른 파일로 바꾼 뒤 [게시]해 주세요.', array('usages' => $usages, 'reason' => 'in-use')); }
  if (count($hist) && !wb_bool(wb_q($c, 'force'))) { throw new WbHttpError(409, '이전 게시본 · 이전 버전에서 사용한 파일입니다. 삭제하면 그 버전으로 복원했을 때 이미지가 비어 보입니다.', array('usages' => $usages, 'reason' => 'history')); }
  wb_update('media', array('deleted_at' => wb_now()), 'id = ?', array((int)$m['id'])); $v = wb_arr($m['variants_json']);
  foreach (array_merge(array($m['filename']), array_values($v)) as $rel) { $f = wb_safe_join(wb_uploads_dir(), (string)$rel); if ($f && is_file($f)) { @unlink($f); } }
  wb_log($c, (int)$m['site_id'], 'media.delete', 'media', (int)$m['id'], '파일 삭제 ' . $m['original_name'] . (count($hist) ? ' (이전 버전에서만 사용)' : '')); return array();
});
wb_route('POST', '/media/:id/replace', function ($c, $p) { $m = wb_media_of($c, $p['id'], 'media'); $f = null; foreach ($c['files'] as $x) { if (preg_match('/^files?$/', $x['field'])) { $f = $x; break; } } if (!$f) { throw new WbHttpError(422, '파일이 없습니다.'); } $data = (string)@file_get_contents($f['tmp']); $sn = wb_sniff($data); $allowed = wb_allowed_types(); if (!$sn || !isset($allowed[$sn['ext']])) { throw new WbHttpError(422, '허용되지 않는 파일 형식입니다.'); } $v = wb_arr($m['variants_json']); $target = wb_safe_join(wb_uploads_dir(), !empty($v['src']) ? $v['src'] : $m['filename']); if (!$target || @file_put_contents($target, $data, LOCK_EX) === false) { throw new WbHttpError(500, '파일을 저장할 수 없습니다. assets/uploads 폴더 권한을 확인해 주세요.'); } $size = strpos($sn['mime'], 'image/') === 0 && $sn['ext'] !== 'svg' ? wb_image_size($target, $sn['ext']) : array(null, null); $tf = wb_file_by_field($c, 'thumb_0'); if ($tf && !empty($v['thumb'])) { @file_put_contents(wb_safe_join(wb_uploads_dir(), $v['thumb']), file_get_contents($tf['tmp']), LOCK_EX); } $mf = wb_file_by_field($c, 'mobile_0'); if ($mf && !empty($v['mobile'])) { @file_put_contents(wb_safe_join(wb_uploads_dir(), $v['mobile']), file_get_contents($mf['tmp']), LOCK_EX); } wb_update('media', array('size' => strlen($data), 'width' => $size[0], 'height' => $size[1], 'hash' => wb_sha256($data), 'mime' => $sn['mime']), 'id = ?', array((int)$m['id'])); wb_log($c, (int)$m['site_id'], 'media.replace', 'media', (int)$m['id'], '파일 교체 ' . $m['original_name']); return array('media' => wb_media_out(wb_get('SELECT * FROM media WHERE id = ?', array((int)$m['id'])), wb_media_base($c))); });

