function wb_popup_out($p, $base) { $n = wb_now(); return array('id' => (int)$p['id'], 'name' => $p['name'], 'type' => $p['type'], 'pc_media_id' => $p['pc_media_id'] ? (int)$p['pc_media_id'] : null, 'mobile_media_id' => $p['mobile_media_id'] ? (int)$p['mobile_media_id'] : null, 'video_media_id' => $p['video_media_id'] ? (int)$p['video_media_id'] : null, 'poster_media_id' => $p['poster_media_id'] ? (int)$p['poster_media_id'] : null, 'pc_src' => $p['pc_media_id'] ? wb_media_by_id((int)$p['pc_media_id'], $base) : (string)$p['pc_src'], 'mobile_src' => $p['mobile_media_id'] ? wb_media_by_id((int)$p['mobile_media_id'], $base, 'mobile') : (string)$p['mobile_src'], 'video_url' => $p['video_media_id'] ? wb_media_by_id((int)$p['video_media_id'], $base) : (string)$p['video_url'], 'poster_src' => $p['poster_media_id'] ? wb_media_by_id((int)$p['poster_media_id'], $base) : '', 'alt' => (string)$p['alt'], 'link' => (string)$p['link'], 'target' => $p['target'] ? $p['target'] : '_self', 'pages' => wb_json_safe($p['pages_json'], array('main')), 'position' => wb_json_safe($p['position_json'], new stdClass()), 'size' => wb_json_safe($p['size_json'], new stdClass()), 'sort' => (int)$p['sort'], 'start_at' => $p['start_at'], 'end_at' => $p['end_at'], 'status' => $p['status'], 'hide_rule' => $p['hide_rule'] ? $p['hide_rule'] : 'today', 'reshow_hours' => $p['reshow_hours'] === null ? null : (int)$p['reshow_hours'], 'devices' => $p['devices'] ? $p['devices'] : 'all', 'priority' => (int)$p['priority'], 'overlay' => $p['overlay'] === null ? null : (float)$p['overlay'], 'options' => wb_json_safe($p['options_json'], new stdClass()), 'impressions' => (int)$p['impressions'], 'clicks' => (int)$p['clicks'], 'created_at' => $p['created_at'], 'updated_at' => $p['updated_at'], 'active' => $p['status'] === 'published' && (!$p['start_at'] || $p['start_at'] <= $n) && (!$p['end_at'] || $p['end_at'] >= $n)); }
function wb_popup_input($c) { $b = $c['body']; $d = array(); foreach (array('name', 'alt', 'link') as $k) { if (wb_has($b, $k)) { $d[$k] = wb_str($b[$k], $k === 'link' ? 500 : 120); } } if (!empty($b['type'])) { $d['type'] = $b['type'] === 'video' ? 'video' : 'image'; } if (!empty($b['target'])) { $d['target'] = $b['target'] === '_blank' ? '_blank' : '_self'; } foreach (array('pc_media_id', 'mobile_media_id', 'video_media_id', 'poster_media_id') as $k) { if (wb_has($b, $k)) { $d[$k] = wb_int($b[$k]) ? wb_int($b[$k]) : null; } } foreach (array('pc_src', 'mobile_src', 'video_url') as $k) { if (wb_has($b, $k)) { $d[$k] = wb_str($b[$k], 500); } } if (wb_has($b, 'pages')) { $pg = array(); if (is_array($b['pages'])) { foreach ($b['pages'] as $x) { $pg[] = (string)$x; } } $d['pages_json'] = wb_enc(count($pg) ? $pg : array('main')); } if (wb_has($b, 'position')) { $d['position_json'] = wb_enc(wb_bo($c, 'position', new stdClass())); } if (wb_has($b, 'size')) { $d['size_json'] = wb_enc(wb_bo($c, 'size', new stdClass())); } if (wb_has($b, 'start_at')) { $d['start_at'] = $b['start_at'] ? str_replace('T', ' ', wb_str($b['start_at'], 19)) : null; } if (wb_has($b, 'end_at')) { $d['end_at'] = $b['end_at'] ? str_replace('T', ' ', wb_str($b['end_at'], 19)) : null; } if (!empty($b['status']) && in_array($b['status'], array('draft', 'published', 'stopped'), true)) { $d['status'] = $b['status']; } if (!empty($b['hide_rule']) && in_array($b['hide_rule'], array('always', 'session', 'today', 'daily'), true)) { $d['hide_rule'] = $b['hide_rule']; } if (!empty($b['devices']) && in_array($b['devices'], array('all', 'pc', 'mobile'), true)) { $d['devices'] = $b['devices']; } if (wb_has($b, 'priority')) { $d['priority'] = wb_int($b['priority']); } if (wb_has($b, 'overlay')) { $d['overlay'] = ($b['overlay'] === '' || $b['overlay'] === null) ? null : max(0, min(1, (float)$b['overlay'])); } if (wb_has($b, 'options')) { $d['options_json'] = wb_enc(wb_bo($c, 'options', new stdClass())); } return $d; }
function wb_popup_of($c, $id) { $p = wb_get("SELECT * FROM popups WHERE id = ? AND status <> 'deleted'", array((int)$id)); if (!$p) { throw new WbHttpError(404, '팝업을 찾을 수 없습니다.'); } wb_site_of($c, (int)$p['site_id'], 'manage'); return $p; }
wb_route('GET', '/sites/:id/popups', function ($c, $p) { $s = wb_site_of($c, $p['id']); $base = wb_media_base($c); $out = array(); foreach (wb_all("SELECT * FROM popups WHERE site_id = ? AND status <> 'deleted' ORDER BY priority DESC, sort, id", array((int)$s['id'])) as $x) { $out[] = wb_popup_out($x, $base); } return array('popups' => $out, 'pages' => wb_all('SELECT `key`, title FROM pages WHERE site_id = ? AND deleted_at IS NULL ORDER BY sort', array((int)$s['id']))); });
wb_route('POST', '/sites/:id/popups', function ($c, $p) { $s = wb_site_of($c, $p['id'], 'manage'); $d = wb_popup_input($c); if (empty($d['name'])) { throw new WbHttpError(422, '관리용 제목을 입력해 주세요.'); } $d = array_merge(array('status' => 'draft', 'hide_rule' => 'today', 'devices' => 'all', 'priority' => 0, 'pages_json' => wb_enc(array('main')), 'position_json' => '{}', 'size_json' => '{}', 'options_json' => '{}', 'type' => 'image', 'target' => '_self'), $d, array('site_id' => (int)$s['id'], 'sort' => wb_int(wb_val('SELECT COALESCE(MAX(sort), 0) + 1 FROM popups WHERE site_id = ?', array((int)$s['id']))), 'reshow_hours' => 24, 'created_by' => (int)$c['user']['id'], 'created_at' => wb_now(), 'updated_at' => wb_now())); $id = wb_insert('popups', $d); wb_log($c, (int)$s['id'], 'popup.create', 'popup', $id, '팝업 등록 ' . $d['name']); return array('popup' => wb_popup_out(wb_get('SELECT * FROM popups WHERE id = ?', array($id)), wb_media_base($c))); });
wb_route('PUT', '/popups/:id', function ($c, $p) { $pp = wb_popup_of($c, $p['id']); $d = wb_popup_input($c); $d['updated_at'] = wb_now(); wb_update('popups', $d, 'id = ?', array((int)$pp['id'])); wb_log($c, (int)$pp['site_id'], 'popup.update', 'popup', (int)$pp['id'], '팝업 수정 ' . (!empty($d['name']) ? $d['name'] : $pp['name'])); return array('popup' => wb_popup_out(wb_get('SELECT * FROM popups WHERE id = ?', array((int)$pp['id'])), wb_media_base($c))); });
wb_route('DELETE', '/popups/:id', function ($c, $p) { $pp = wb_popup_of($c, $p['id']); wb_update('popups', array('status' => 'deleted', 'updated_at' => wb_now()), 'id = ?', array((int)$pp['id'])); wb_log($c, (int)$pp['site_id'], 'popup.delete', 'popup', (int)$pp['id'], '팝업 삭제 ' . $pp['name']); return array(); });
wb_route('POST', '/sites/:id/popups/reorder', function ($c, $p) { $s = wb_site_of($c, $p['id'], 'manage'); $i = 0; foreach ((array)wb_b($c, 'ids', array()) as $id) { wb_update('popups', array('sort' => $i++), 'id = ? AND site_id = ?', array(wb_int($id), (int)$s['id'])); } return array(); });

/* ================= SEO (최종 제목 · 설명 계산과 sitemap 미리보기는 관리자 화면이 공유 코어(WBCore)로 계산) ================= */
function wb_seo_row($r) { if (!$r) { return array('title' => '', 'description' => '', 'keywords' => '', 'canonical' => '', 'robots' => 'index,follow', 'og' => new stdClass(), 'structured' => null, 'verification' => new stdClass(), 'favicon_media_id' => null, 'share_image_media_id' => null, 'mode' => '', 'title_rule' => 'page_site', 'noindex' => false); } $og = wb_json_safe($r['og_json'], new stdClass()); if (is_object($og) && isset($og->image) && is_string($og->image) && preg_match('#^https?://(www\.)?example\.com/#i', $og->image)) { $og->image = preg_replace('#^https?://(www\.)?example\.com/#i', './', $og->image); } return array('title' => (string)$r['title'], 'description' => (string)$r['description'], 'keywords' => (string)$r['keywords'], 'canonical' => (string)$r['canonical'], 'robots' => $r['robots'] ? $r['robots'] : 'index,follow', 'og' => is_object($og) ? $og : new stdClass(), 'structured' => wb_json_safe($r['structured_json'], null), 'verification' => wb_json_safe($r['verification_json'], new stdClass()), 'favicon_media_id' => $r['favicon_media_id'] ? (int)$r['favicon_media_id'] : null, 'share_image_media_id' => $r['share_image_media_id'] ? (int)$r['share_image_media_id'] : null, 'mode' => (string)$r['mode'], 'title_rule' => $r['title_rule'] ? $r['title_rule'] : 'page_site', 'noindex' => (int)$r['noindex'] === 1); }
function wb_seo_input($c) { $b = $c['body']; $d = array('updated_at' => wb_now()); foreach (array('title', 'description', 'keywords', 'canonical', 'robots') as $k) { if (wb_has($b, $k)) { $d[$k] = wb_str($b[$k], $k === 'description' ? 500 : ($k === 'keywords' ? 250 : 190)); } } if (!empty($d['canonical']) && preg_match('#^https?://(localhost|127\.0\.0\.1|(www\.)?example\.com)#i', $d['canonical'])) { throw new WbHttpError(422, '대표 주소(canonical)에는 실제 공개 도메인을 입력해 주세요. (localhost · example.com 은 사용할 수 없습니다)'); } if (wb_has($b, 'og')) { $d['og_json'] = wb_enc(wb_bo($c, 'og', new stdClass())); } if (wb_has($b, 'structured')) { $d['structured_json'] = wb_enc(wb_bo($c, 'structured')); } if (wb_has($b, 'verification')) { $d['verification_json'] = wb_enc(wb_bo($c, 'verification', new stdClass())); } if (wb_has($b, 'favicon_media_id')) { $d['favicon_media_id'] = wb_int($b['favicon_media_id']) ? wb_int($b['favicon_media_id']) : null; } if (wb_has($b, 'share_image_media_id')) { $d['share_image_media_id'] = wb_int($b['share_image_media_id']) ? wb_int($b['share_image_media_id']) : null; } if (wb_has($b, 'mode')) { $d['mode'] = in_array($b['mode'], array('inherit', 'auto', 'custom'), true) ? $b['mode'] : null; } if (wb_has($b, 'title_rule')) { $d['title_rule'] = in_array($b['title_rule'], array('page_site', 'site_page', 'site'), true) ? $b['title_rule'] : 'page_site'; } if (wb_has($b, 'noindex')) { $d['noindex'] = wb_bool($b['noindex']) ? 1 : 0; } return $d; }
wb_route('GET', '/sites/:id/seo', function ($c, $p) { $s = wb_site_of($c, $p['id']); $base = wb_media_base($c); $site = wb_get("SELECT * FROM seo WHERE site_id = ? AND scope = 'site'", array((int)$s['id'])); $pages = array(); foreach (wb_all('SELECT id, `key`, type, title, status, updated_at FROM pages WHERE site_id = ? AND deleted_at IS NULL ORDER BY sort', array((int)$s['id'])) as $pg) { $pg = wb_ints($pg, array('id')); $row = wb_get("SELECT * FROM seo WHERE site_id = ? AND scope = 'page' AND page_id = ?", array((int)$s['id'], (int)$pg['id'])); $pg['seo'] = wb_seo_row($row); $pg['image'] = $row && $row['share_image_media_id'] ? wb_media_by_id((int)$row['share_image_media_id'], $base) : ''; $pg['resolved'] = new stdClass(); $pg['mode'] = $row && $row['mode'] ? $row['mode'] : 'inherit'; $pg['path'] = $pg['type'] === 'main' ? '/' : '/index.html#page=' . $pg['key']; $pages[] = $pg; } $pub = wb_site_url($s); return array('site' => wb_seo_row($site), 'favicon' => $site && $site['favicon_media_id'] ? wb_media_by_id((int)$site['favicon_media_id'], $base) : '', 'shareImage' => $site && $site['share_image_media_id'] ? wb_media_by_id((int)$site['share_image_media_id'], $base) : '', 'pages' => $pages, 'resolved' => new stdClass(), 'clientResolve' => true, 'publicUrl' => $pub, 'domainOk' => preg_match('#^https?://#', $pub) === 1 && !preg_match('/localhost|127\.0\.0\.1|example\.com/i', $pub), 'sitemap' => $pub ? $pub . '/sitemap.xml' : '', 'robotsUrl' => $pub ? $pub . '/robots.txt' : '', 'sitemapPreview' => '', 'robotsPreview' => '', 'ftp' => false); });
