wb_route('GET', '/sites/:id/analytics', function ($c, $p) { $s = wb_site_of($c, $p['id'], 'stats'); $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', wb_q($c, 'to')) ? wb_q($c, 'to') : wb_today(); $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', wb_q($c, 'from')) ? wb_q($c, 'from') : wb_today(wb_days(-29, strtotime($to . ' 00:00:00'))); if ($from > $to) { $from = $to; } $days = (int)round((strtotime($to . ' 00:00:00') - strtotime($from . ' 00:00:00')) / 86400) + 1; $prevTo = wb_today(wb_days(-1, strtotime($from . ' 00:00:00'))); $prevFrom = wb_today(wb_days(-$days, strtotime($from . ' 00:00:00'))); return array('from' => $from, 'to' => $to, 'report' => wb_report((int)$s['id'], $from, $to), 'prev' => wb_report((int)$s['id'], $prevFrom, $prevTo), 'popups' => array_map(function ($r) { return wb_ints($r, array('id', 'impressions', 'clicks')); }, wb_all("SELECT id, name, type, impressions, clicks FROM popups WHERE site_id = ? AND status <> 'deleted' ORDER BY impressions DESC LIMIT 20", array((int)$s['id']))), 'analytics' => wb_get_setting((int)$s['id'], 'analytics')); });

