function wb_user_out($u) { $o = wb_public_user($u); $o['login_fails'] = (int)(isset($u['failed_logins']) ? $u['failed_logins'] : 0); $o['locked'] = !empty($u['locked_until']) && $u['locked_until'] > wb_now(); $o['locked_until'] = !empty($u['locked_until']) ? $u['locked_until'] : null; $o['sites'] = array_map(function ($r) { return wb_ints($r, array('site_id')); }, wb_all('SELECT su.site_id, su.role, s.name FROM site_users su JOIN sites s ON s.id = su.site_id WHERE su.user_id = ?', array((int)$u['id']))); $o['advertisers'] = array_map(function ($r) { return wb_ints($r, array('advertiser_id')); }, wb_all('SELECT ua.advertiser_id, ua.role, a.name FROM user_advertisers ua JOIN advertisers a ON a.id = ua.advertiser_id WHERE ua.user_id = ?', array((int)$u['id']))); return $o; }
function wb_set_user_advertisers($uid, $list) { if (!is_array($list)) { return; } wb_del('user_advertisers', 'user_id = ?', array((int)$uid)); foreach ($list as $a) { $aid = is_array($a) ? wb_int(isset($a['advertiser_id']) ? $a['advertiser_id'] : 0) : wb_int($a); if (!$aid) { continue; } $role = is_array($a) && isset($a['role']) && in_array($a['role'], wb_site_roles(), true) ? $a['role'] : 'staff'; wb_insert('user_advertisers', array('advertiser_id' => $aid, 'user_id' => (int)$uid, 'role' => $role, 'created_at' => wb_now())); } }
