function wb_user_sms_check($d, $old) { $on = isset($d['sms_notify']) ? (int)$d['sms_notify'] : ($old ? (int)$old['sms_notify'] : 0); $ph = isset($d['phone']) ? $d['phone'] : ($old ? (string)$old['phone'] : ''); if ($on && trim((string)$ph) !== '' && wb_sms_mobile($ph) === '') { throw new WbHttpError(422, '방문예약 문자를 받으려면 휴대전화번호(010-1234-5678 형식)를 입력해 주세요.'); } }   /* 비워 두면 저장은 되고 문자만 안 감 (화면에 "문자 수신번호가 등록되지 않았습니다." 안내) */
function wb_user_input($b, $isNew) { $d = array(); $roles = wb_roles(); if (wb_has($b, 'login_id')) { $id = wb_lower(trim(wb_str($b['login_id']))); if (!preg_match('/^[a-z0-9_.@\-]{3,40}$/', $id)) { throw new WbHttpError(422, '로그인 아이디는 영문 · 숫자 3~40자입니다.'); } $d['login_id'] = $id; } foreach (array('name', 'email', 'phone', 'company', 'tel') as $k) { if (wb_has($b, $k)) { $d[$k] = trim(wb_str($b[$k], 120)); } } if (isset($d['email'])) { $d['email'] = wb_lower($d['email']); } if (wb_has($b, 'role')) { if (!isset($roles[$b['role']])) { throw new WbHttpError(422, '권한 그룹이 올바르지 않습니다.'); } $d['role'] = $b['role']; } if (wb_has($b, 'status')) { $d['status'] = in_array($b['status'], array('active', 'inactive'), true) ? $b['status'] : 'active'; } if (!empty($b['password'])) { $err = wb_valid_password($b['password']); if ($err) { throw new WbHttpError(422, $err); } $d['password_hash'] = wb_hash_password($b['password']); $d['must_change_password'] = 0; } if (isset($d['phone']) && $d['phone'] !== '') { $m = wb_sms_mobile($d['phone']); if ($m === '') { throw new WbHttpError(422, '휴대전화번호 형식이 올바르지 않습니다. (예 : 010-1234-5678)'); } $d['phone'] = wb_sms_pretty($m); } if (wb_has($b, 'sms_notify')) { $d['sms_notify'] = wb_bool($b['sms_notify']) ? 1 : 0; } if ($isNew && empty($d['login_id'])) { throw new WbHttpError(422, '로그인 아이디를 입력해 주세요.'); } if ($isNew && empty($d['password_hash'])) { throw new WbHttpError(422, '초기 비밀번호를 입력해 주세요.'); } return $d; }
wb_route('GET', '/users', function ($c) { wb_must_super($c['user']); $adv = array(); foreach (wb_advertisers($c['user']) as $a) { $adv[] = array('id' => (int)$a['id'], 'name' => $a['name']); } return array('advertisers' => $adv, 'siteRoles' => wb_site_roles(), 'users' => array_map('wb_user_out', wb_all('SELECT * FROM users ORDER BY id')), 'roles' => wb_roles(), 'sites' => array_map(function ($r) { return wb_ints($r, array('id')); }, wb_all("SELECT id, name, `key` FROM sites WHERE status <> 'deleted' ORDER BY id"))); });
