wb_route('PUT', '/users/:id', function ($c, $p) { wb_must_super($c['user']); $u = wb_get('SELECT * FROM users WHERE id = ?', array((int)$p['id'])); if (!$u) { throw new WbHttpError(404, '계정을 찾을 수 없습니다.'); } $d = wb_user_input($c['body'], false); wb_user_sms_check($d, $u); $me = (int)$u['id'] === (int)$c['user']['id']; if ($me && ((!empty($d['role']) && $d['role'] !== 'super') || (isset($d['status']) && $d['status'] === 'inactive'))) { throw new WbHttpError(422, '자신의 권한이나 상태는 변경할 수 없습니다.'); } if (!empty($d['login_id']) && wb_get('SELECT id FROM users WHERE LOWER(login_id) = ? AND id <> ?', array($d['login_id'], (int)$u['id']))) { throw new WbHttpError(422, '이미 사용 중인 아이디입니다.'); } $d['updated_at'] = wb_now(); wb_update('users', $d, 'id = ?', array((int)$u['id'])); if (wb_has($c['body'], 'sites')) { wb_set_user_sites((int)$u['id'], wb_b($c, 'sites', array())); } if (wb_has($c['body'], 'advertisers')) { wb_set_user_advertisers((int)$u['id'], wb_b($c, 'advertisers')); } $newToken = null; if ((isset($d['status']) && $d['status'] === 'inactive') || !empty($d['password_hash'])) { wb_logout_all((int)$u['id']); if ($me && !empty($d['password_hash'])) { $newToken = wb_create_session((int)$u['id'], $c); } } wb_log($c, null, 'user.update', 'user', (int)$u['id'], '계정 수정 ' . (!empty($d['login_id']) ? $d['login_id'] : $u['login_id']), null, array_keys($d)); $out = array('user' => wb_user_out(wb_get('SELECT * FROM users WHERE id = ?', array((int)$u['id'])))); if ($newToken) { $out['token'] = $newToken; } return $out; });
wb_route('DELETE', '/users/:id', function ($c, $p) { wb_must_super($c['user']); $u = wb_get('SELECT * FROM users WHERE id = ?', array((int)$p['id'])); if (!$u) { throw new WbHttpError(404, '계정을 찾을 수 없습니다.'); } if ((int)$u['id'] === (int)$c['user']['id']) { throw new WbHttpError(422, '자신의 계정은 삭제할 수 없습니다.'); } if ($u['role'] === 'super' && wb_int(wb_val("SELECT COUNT(*) FROM users WHERE role = 'super' AND status = 'active'")) <= 1) { throw new WbHttpError(422, '마지막 최고관리자는 삭제할 수 없습니다.'); } $t = time(); wb_update('users', array('status' => 'inactive', 'updated_at' => wb_now(), 'login_id' => $u['login_id'] . '.deleted.' . $t, 'email' => $u['email'] . '.deleted.' . $t), 'id = ?', array((int)$u['id'])); wb_logout_all((int)$u['id']); wb_del('site_users', 'user_id = ?', array((int)$u['id'])); wb_del('user_advertisers', 'user_id = ?', array((int)$u['id'])); wb_log($c, null, 'user.delete', 'user', (int)$u['id'], '계정 삭제 ' . $u['login_id']); return array(); });
