wb_route('GET', '/sites/:id/logs', function ($c, $p) { $s = wb_site_of($c, $p['id'], 'logs'); $page = max(1, wb_int(wb_q($c, 'page', 1), 1)); $per = 30; $where = array((wb_q($c, 'global') === '1' && wb_is_super($c['user'])) ? '(l.site_id = ? OR l.site_id IS NULL)' : 'l.site_id = ?'); $params = array((int)$s['id']); if (wb_q($c, 'q') !== '') { $where[] = '(l.summary LIKE ? OR l.action LIKE ?)'; $params[] = '%' . wb_q($c, 'q') . '%'; $params[] = '%' . wb_q($c, 'q') . '%'; } $w = implode(' AND ', $where); $total = wb_int(wb_val('SELECT COUNT(*) FROM activity_logs l WHERE ' . $w, $params)); return array('rows' => array_map(function ($r) { return wb_ints($r, array('id', 'target_id')); }, wb_all('SELECT l.id, l.action, l.target_type, l.target_id, l.summary, l.created_at, u.name AS user_name FROM activity_logs l LEFT JOIN users u ON u.id = l.user_id WHERE ' . $w . ' ORDER BY l.id DESC LIMIT ' . $per . ' OFFSET ' . (($page - 1) * $per), $params)), 'total' => $total, 'page' => $page, 'pages' => max(1, (int)ceil($total / $per)), 'access' => wb_can($c['user'], (int)$s['id'], 'submissions') ? array_map(function ($r) { return wb_ints($r, array('submission_id')); }, wb_all('SELECT l.action, l.detail, l.submission_id, l.created_at, u.name AS user_name FROM submission_access_logs l LEFT JOIN users u ON u.id = l.user_id WHERE l.site_id = ? ORDER BY l.id DESC LIMIT 30', array((int)$s['id']))) : array()); });
