wb_route('GET', '/sites/:id/search', function ($c, $p) { $s = wb_site_of($c, $p['id']); $q = trim(wb_q($c, 'q')); if ($q === '') { return array('results' => array()); } $like = '%' . $q . '%'; $results = array(); foreach (wb_all('SELECT id, `key`, title FROM pages WHERE site_id = ? AND deleted_at IS NULL AND (title LIKE ? OR `key` LIKE ?) LIMIT 10', array((int)$s['id'], $like, $like)) as $r) { $results[] = array('type' => 'page', 'id' => (int)$r['id'], 'title' => $r['title'], 'hint' => $r['key']); } if (wb_can($c['user'], (int)$s['id'], 'media')) { foreach (wb_all('SELECT id, original_name FROM media WHERE site_id = ? AND deleted_at IS NULL AND (original_name LIKE ? OR alt LIKE ?) LIMIT 10', array((int)$s['id'], $like, $like)) as $r) { $results[] = array('type' => 'media', 'id' => (int)$r['id'], 'title' => $r['original_name']); } } if (wb_can($c['user'], (int)$s['id'], 'submissions')) { foreach (wb_all('SELECT id, name, phone, created_at FROM form_submissions WHERE site_id = ? AND deleted_at IS NULL AND (name LIKE ? OR phone LIKE ?) ORDER BY id DESC LIMIT 10', array((int)$s['id'], $like, $like)) as $r) { $results[] = array('type' => 'submission', 'id' => (int)$r['id'], 'title' => $r['name'] . ' · ' . $r['phone'], 'hint' => $r['created_at']); } } return array('results' => $results); });

/* ================= 시스템 (최고관리자) : 백업은 DB 전체를 JSON 으로 api/data/backups/ 에 저장 (파일명 .php + 첫 줄 exit 로 웹에서 직접 열어도 내용이 보이지 않음) ================= */
function wb_backup_tables() { return array('advertisers', 'users', 'user_advertisers', 'sites', 'site_users', 'settings', 'menus', 'menu_items', 'section_types', 'pages', 'page_versions', 'forms', 'form_fields', 'form_submissions', 'submission_histories', 'sms_logs', 'submission_access_logs', 'media_folders', 'media', 'popups', 'seo', 'publish_snapshots', 'analytics_daily', 'activity_logs', 'login_logs', 'system_settings'); }
function wb_make_backup($c, $label = '') { $dir = WB_DATA_DIR . '/backups'; if (!is_dir($dir)) { @mkdir($dir, 0755, true); } $stamp = date('Ymd-His'); $name = 'backup-' . $stamp . ($label !== '' ? '-' . preg_replace('/[^a-z0-9\-]/', '', wb_slugify($label)) : '') . '.php'; $tables = array(); foreach (wb_backup_tables() as $t) { $tables[$t] = wb_all('SELECT * FROM `' . $t . '`'); } $json = wb_enc(array('created_at' => wb_now(), 'version' => WB_VERSION, 'schema' => WB_SCHEMA_VERSION, 'sites' => wb_all('SELECT `key`, name FROM sites'), 'tables' => $tables)); $text = "<?php exit; ?>\n" . $json; if (!wb_write_atomic($dir . '/' . $name, $text)) { throw new WbHttpError(500, '백업 파일을 저장할 수 없습니다. api/data 폴더 권한을 확인해 주세요.'); } $keep = wb_int(wb_prop(wb_system_settings(), 'backupKeep', 14), 14); $list = glob($dir . '/backup-*.php'); sort($list); while (count($list) > max(1, $keep)) { @unlink(array_shift($list)); } return array('name' => $name, 'bytes' => strlen($text)); }
/* 하루 1회 정리(그날 첫 로그인 때 · 운영 서버에는 예약 작업이 없으므로) : 보관기간 지난 예약 파기 · 오래된 통계 원본 · 만료 세션 · 자동 백업 */
function wb_daily_tasks($c) { try { $set = wb_system_settings(); $today = wb_today(); if (wb_prop($set, 'lastDaily') === $today) { return; } if (wb_get('SELECT `key` FROM system_settings WHERE `key` = ?', array('lastDaily'))) { wb_update('system_settings', array('value' => wb_enc($today), 'updated_at' => wb_now()), '`key` = ?', array('lastDaily')); } else { wb_insert('system_settings', array('key' => 'lastDaily', 'value' => wb_enc($today), 'updated_at' => wb_now())); } $n = 0;   /* 개인정보 자동 파기 안 함 (방문예약은 계속 보관 · 삭제는 관리자가 직접) */ $keep = wb_int(wb_prop($set, 'analyticsKeepDays', 400), 400); if ($keep > 0) { wb_del('analytics_events', 'created_at < ?', array(wb_now(wb_days(-$keep)))); } wb_del('user_sessions', 'expires_at < ?', array(wb_now())); wb_del('preview_tokens', 'expires_at < ?', array(wb_now())); wb_del('rate_limits', 'window_start < ?', array((string)(time() - 3600))); if (wb_prop($set, 'autoBackup', true) !== false) { wb_make_backup($c, 'auto'); } if ($n) { wb_log($c, null, 'submission.purge', 'submission', null, '보관기간 경과 ' . $n . '건 자동 파기'); } } catch (Exception $e) { wb_log_error('daily: ' . $e->getMessage()); } }
wb_route('GET', '/system/status', function ($c) { wb_must_super($c['user']); return array('status' => wb_system_status($c), 'settings' => wb_system_settings()); });
wb_route('PUT', '/system/settings', function ($c) { wb_must_super($c['user']); $b = $c['body']; if (wb_has($b, 'publicBaseUrl')) { $u = rtrim(trim(wb_str($b['publicBaseUrl'], 200)), '/'); if ($u !== '' && !preg_match('#^https?://[^\s/]+(/[^\s]*)?$#', $u)) { throw new WbHttpError(422, '서버 공개 주소는 http:// 또는 https:// 로 시작하는 주소여야 합니다.'); } $b['publicBaseUrl'] = $u; } foreach ($b as $k => $v) { if (!preg_match('/^[a-zA-Z]{1,40}$/', (string)$k)) { continue; } $val = wb_enc(is_array($v) ? wb_bo($c, $k, $v) : $v); if (wb_get('SELECT `key` FROM system_settings WHERE `key` = ?', array($k))) { wb_update('system_settings', array('value' => $val, 'updated_at' => wb_now()), '`key` = ?', array($k)); } else { wb_insert('system_settings', array('key' => $k, 'value' => $val, 'updated_at' => wb_now())); } } wb_log($c, null, 'system.settings', 'system', null, '시스템 설정 변경'); return array('settings' => wb_system_settings()); });
wb_route('GET', '/system/sms', function ($c) { wb_must_super($c['user']); return wb_sms_status($c); });
wb_route('PUT', '/system/sms', function ($c) {   /* 문자 업체 설정 저장 (최고관리자) — 비밀키 · API Key 는 비워 두면 기존 값 유지, 화면에 다시 표시하지 않음 */
  wb_must_super($c['user']);
  throw new WbHttpError(403, '문자 업체 설정(API Key · API Secret · 발신번호)은 서버의 api/config.php 에서만 변경합니다. 관리자 화면에서는 저장하지 않습니다.');   /* 운영 : 키는 서버 설정 파일에만 (화면 저장 경로 닫음) */
  $b = $c['body']; $old = wb_sms_cfg($c);
  $p = strtolower(trim(wb_str(isset($b['provider']) ? $b['provider'] : ''))); if (!in_array($p, array('', 'solapi', 'aligo', 'ncp', 'log'), true)) { throw new WbHttpError(422, '지원하지 않는 문자 업체입니다.'); }
  $v = function ($k) use ($b) { return isset($b[$k]) ? trim(wb_str($b[$k], 300)) : ''; };
  $key = $v('api_key') !== '' ? $v('api_key') : ($p === $old['provider'] || $p === '' ? $old['api_key'] : ''); $sec = $v('api_secret') !== '' ? $v('api_secret') : ($p === $old['provider'] || $p === '' ? $old['api_secret'] : '');
  if (!empty($b['clear_keys'])) { $key = ''; $sec = ''; }
  $sender = wb_sms_digits($v('sender')); if ($sender !== '' && !preg_match('/^(0\d{8,10}|1[5-9]\d{6})$/', $sender)) { throw new WbHttpError(422, '발신번호 형식이 올바르지 않습니다. (문자 업체에 등록 · 인증된 번호 · 예 02-1234-5678)'); }
  $data = array('provider' => $p, 'api_key' => $key, 'api_secret' => $sec, 'sender' => $sender, 'user_id' => $v('user_id'), 'service_id' => $v('service_id'));
  $why = $p === '' ? '' : wb_sms_ready(array_merge($old, $data, array('enabled' => true)));
  if ($why !== '') { throw new WbHttpError(422, '입력이 부족합니다 : ' . $why); }
  wb_sms_save_file($data);
  wb_log($c, null, 'system.sms_settings', 'system', null, '문자 설정 저장 · ' . ($p === '' ? '사용 안 함' : $p) . ($sender !== '' ? ' · 발신 ' . wb_sms_pretty($sender) : ''));
  return wb_sms_status(array_merge($c, array('config' => $c['config'])));
});
wb_route('POST', '/system/sms/test', function ($c) { wb_must_super($c['user']); if (!wb_rate('smstest:' . (int)$c['user']['id'], 3, 60)) { throw new WbHttpError(429, '잠시 후 다시 시도해 주세요.'); } $me = wb_get('SELECT phone FROM users WHERE id = ?', array((int)$c['user']['id'])); $to = wb_sms_mobile($me ? $me['phone'] : ''); if ($to === '') { throw new WbHttpError(422, '내 계정에 휴대전화번호를 먼저 입력해 주세요. (테스트 문자는 로그인한 최고관리자 본인 번호로만 보냅니다)'); } $cfg = wb_sms_cfg($c); $text = '[통합웹빌더] 문자 알림 테스트입니다.'; $r = wb_sms_send_logged($cfg, $to, $text, wb_sms_type($text), '문자 알림 테스트', 'test', 0);
  wb_log($c, null, 'system.sms_test', 'system', null, '문자 테스트 ' . wb_sms_mask($to) . ' · ' . ($r['ok'] ? '성공' : '실패 ' . $r['code'] . ($r['kind'] ? ' (' . $r['kind'] . ')' : '')));
  $ip = $r['ip'] !== '' ? $r['ip'] : ''; if (!$r['ok'] && $r['kind'] === 'ip' && $ip === '') { $x = wb_sms_server_ip(false); $ip = $x['ip']; }
  return array('ok' => (bool)$r['ok'], 'to' => wb_sms_mask($to), 'kind' => $r['kind'], 'label' => $r['label'], 'reason' => $r['reason'], 'code' => $r['ok'] ? '' : (string)$r['code'], 'raw' => $r['raw'], 'error' => $r['ok'] ? '' : $r['reason'], 'serverIp' => $ip, 'cidr' => $ip !== '' ? $ip . '/32' : ''); });
wb_route('GET', '/system/sms/ip', function ($c) {   /* 현재 서버 발신 IP (문자 업체가 인식하는 공인 IP · 6시간 보관, refresh=1 이면 새로 확인) */
  wb_must_super($c['user']); $x = wb_sms_server_ip(!empty($c['query']['refresh']));
  return array('ip' => (string)$x['ip'], 'cidr' => $x['ip'] !== '' ? $x['ip'] . '/32' : '', 'at' => (string)$x['at'], 'source' => (string)$x['src']); });
wb_route('POST', '/system/backup', function ($c) { wb_must_super($c['user']); $r = wb_make_backup($c, wb_str(wb_b($c, 'label'), 30)); wb_log($c, null, 'system.backup', 'system', null, '백업 생성 ' . $r['name'] . ' (' . wb_fmt_bytes($r['bytes']) . ')'); return $r; });
wb_route('GET', '/system/backups', function ($c) { wb_must_super($c['user']); $dir = WB_DATA_DIR . '/backups'; $list = array(); if (is_dir($dir)) { $files = glob($dir . '/backup-*.php'); rsort($files); foreach ($files as $f) { $list[] = array('name' => basename($f), 'bytes' => filesize($f), 'created_at' => wb_now(filemtime($f))); } } return array('backups' => $list, 'note' => '백업 파일은 api/data/backups/ 에 저장됩니다. FileZilla 로 내려받아 따로 보관하세요.'); });
wb_route('GET', '/system/backups/:name', function ($c, $p) { wb_must_super($c['user']); $f = wb_safe_join(WB_DATA_DIR . '/backups', basename((string)$p['name'])); if (!$f || !is_file($f) || !preg_match('/^backup-[a-z0-9\-]+\.php$/', basename($f))) { throw new WbHttpError(404, '백업 파일을 찾을 수 없습니다.'); } wb_log($c, null, 'system.backup_download', 'system', null, '백업 다운로드 ' . basename($f)); $raw = file_get_contents($f); $pos = strpos($raw, "\n"); wb_send_file(200, 'application/json; charset=utf-8', $pos === false ? '' : substr($raw, $pos + 1), preg_replace('/\.php$/', '.json', basename($f))); return null; });
wb_route('DELETE', '/system/backups/:name', function ($c, $p) { wb_must_super($c['user']); $f = wb_safe_join(WB_DATA_DIR . '/backups', basename((string)$p['name'])); if ($f && is_file($f) && preg_match('/^backup-[a-z0-9\-]+\.php$/', basename($f))) { @unlink($f); } return array(); });
wb_route('POST', '/system/restore', function ($c) {
  wb_must_super($c['user']); $raw = ''; if (count($c['files'])) { $raw = (string)@file_get_contents($c['files'][0]['tmp']); } elseif (wb_b($c, 'name')) { $f = wb_safe_join(WB_DATA_DIR . '/backups', basename(wb_str(wb_b($c, 'name')))); if ($f && is_file($f)) { $raw = (string)file_get_contents($f); } }
  if ($raw === '') { throw new WbHttpError(422, '복구할 백업 파일을 선택해 주세요.'); } if (strpos($raw, '<?php') === 0) { $pos = strpos($raw, "\n"); $raw = $pos === false ? '' : substr($raw, $pos + 1); }
  $d = json_decode($raw, true); if (!is_array($d) || empty($d['tables']) || !is_array($d['tables'])) { throw new WbHttpError(422, '백업 파일 형식이 올바르지 않습니다. (이 프로그램의 [백업 생성]으로 만든 파일만 복구할 수 있습니다)'); }
  wb_make_backup($c, 'before-restore'); $schema = wb_schema(); $me = (int)$c['user']['id']; $n = 0;
  wb_tx(function () use ($d, $schema, &$n) { foreach (wb_backup_tables() as $t) { if (!isset($d['tables'][$t]) || !is_array($d['tables'][$t]) || !isset($schema[$t])) { continue; } $cols = array(); foreach ($schema[$t] as $col) { if ($col[0][0] !== '_') { $cols[$col[0]] = true; } } wb_run('DELETE FROM `' . $t . '`'); foreach ($d['tables'][$t] as $row) { $ins = array(); foreach ((array)$row as $k => $v) { if (isset($cols[$k])) { $ins[$k] = $v; } } if (count($ins)) { wb_insert($t, $ins); $n++; } } } });
  wb_del('user_sessions', '1 = 1'); $u = wb_get('SELECT * FROM users WHERE id = ?', array($me)); if ($u) { $c['user'] = $u; }
  wb_log($c, null, 'system.restore', 'system', null, '백업 복구 (' . $n . ' 행)'); return array('restored' => $n, 'note' => '복구가 완료되었습니다. 모든 사용자는 다시 로그인해야 합니다.');
});
wb_route('GET', '/system/errors', function ($c) { wb_must_super($c['user']); $dir = WB_DATA_DIR . '/logs'; $out = array(); if (is_dir($dir)) { $files = glob($dir . '/error-*'); rsort($files); foreach (array_slice($files, 0, 7) as $f) { $lines = file($f, FILE_IGNORE_NEW_LINES); $lines = array_values(array_filter($lines, function ($l) { return strpos($l, '<?php') !== 0; })); $out[] = array('file' => basename($f), 'tail' => implode("\n", array_slice($lines, -60))); } } return array('files' => $out); });

