wb_route('POST', '/public/:key/events', function ($c, $p) { $s = wb_public_site($c, $p['key']); $cfg = wb_get_setting((int)$s['id'], 'analytics'); if (isset($cfg->enabled) && $cfg->enabled === false) { return array('skipped' => true); } $b = $c['body']; $events = isset($b['events']) && is_array($b['events']) ? $b['events'] : array($b); $sid = preg_replace('/[^a-zA-Z0-9]/', '', wb_str(isset($b['sid']) ? $b['sid'] : '')); $sessionHash = wb_sha256(($sid !== '' ? $sid : ($c['ipHash'] . $c['ua'])) . '|' . wb_today()); $n = 0; foreach (array_slice($events, 0, 20) as $ev) { if (!is_array($ev)) { continue; } $event = isset($ev['event']) && in_array($ev['event'], array('pageview', 'click', 'submit'), true) ? $ev['event'] : 'pageview'; $utm = array(); foreach (array('utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content') as $k) { if (isset($ev['utm']) && is_array($ev['utm']) && !empty($ev['utm'][$k])) { $utm[$k] = wb_str($ev['utm'][$k], 100); } } wb_insert('analytics_events', array('site_id' => (int)$s['id'], 'session_hash' => $sessionHash, 'event' => $event, 'path' => wb_str(!empty($ev['path']) ? $ev['path'] : '/', 190), 'title' => wb_str(isset($ev['title']) ? $ev['title'] : '', 190), 'label' => wb_str(isset($ev['label']) ? $ev['label'] : '', 120), 'referrer_host' => wb_str(wb_host_of(isset($ev['referrer']) ? (string)$ev['referrer'] : ''), 120), 'device' => isset($ev['device']) && in_array($ev['device'], array('pc', 'tablet', 'mobile'), true) ? $ev['device'] : 'pc', 'screen_w' => !empty($ev['screen_w']) ? wb_int($ev['screen_w']) : null, 'screen_h' => !empty($ev['screen_h']) ? wb_int($ev['screen_h']) : null, 'utm_json' => count($utm) ? wb_enc($utm) : null, 'created_at' => wb_now())); $n++; } return array('count' => $n); }, array('open' => true));
